// ============================================================================
//  "Rename plan"  —  REPLACEMENT. Paste the whole file.
//  Mode: Run Once for All Items (default).
//
//  For every row of papers_batch1_results, builds
//      new_folder_name = {nnn}_{surname1-surname2-...}_{title-slug}_{variant}
//  and finds the folder that CURRENTLY holds that row's slides on disk.
//
//  It does not trust the sheet's folder_name column, because the previous
//  version wrote new names into it even on a DRY_RUN. It looks for the
//  current folder on disk in this order:
//    1. the new name (already renamed on an earlier run)
//    2. the sheet's folder_name
//    3. the original name recorded in notes ("Folder renamed: X -> ...")
//    4. the original naming pattern {FirstSurname}_{title-slug}_{variant}_{index}
//
//  Numbering: one number per paper (drive_file_id), in sheet order, so the
//  applied and research folders of one paper share a number.
//  This node only READS the disk, so it is safe on a dry run.
// ============================================================================

const fs = require('fs');
const g = $('Globals').first().json;
const root = String(g.LOCAL_OUTPUT_ROOT || '').replace(/[\\/]+$/, '');

if (!root || !fs.existsSync(root)) {
  throw new Error(
    `LOCAL_OUTPUT_ROOT "${root}" does not exist as seen from this Code node. ` +
    `If n8n runs Code nodes in a separate task-runner container, that container ` +
    `needs the same volume mount as the main n8n container.`
  );
}

const onDisk = new Set(
  fs.readdirSync(root, { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .map((d) => d.name)
);

// ---------------------------------------------------------------------------
//  Exact copies of the helpers in "Compute Local Path".
//  Used to rebuild the ORIGINAL folder names, so do not "improve" them.
// ---------------------------------------------------------------------------
function slug(s, maxWords = 6, maxChars = 40) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, maxWords)
    .join('-')
    .slice(0, maxChars)
    .replace(/-+$/, '');
}

function originalSurname(authors) {
  const first = String(authors || '').split(/,| and | & /i)[0].trim();
  const parts = first.split(/\s+/).filter(Boolean);
  const last = parts[parts.length - 1] || 'unknown';
  return last.replace(/[^a-zA-Z0-9-]/g, '') || 'unknown';
}

// ---------------------------------------------------------------------------
//  Helpers for the NEW name
// ---------------------------------------------------------------------------
const MAX_AUTHOR_CHARS = 80; // Windows paths cap at 260 chars; long lists end in "-etal"

function cleanName(s) {
  return String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // Müller -> Muller
    .replace(/[^a-zA-Z0-9-]/g, '');
}

function allSurnames(authors) {
  return String(authors || '')
    .split(/\s*[,;&]\s*|\s+and\s+/i)
    .map((name) => name.trim().split(/\s+/).filter(Boolean).pop())
    .map(cleanName)
    .filter(Boolean);
}

function authorPart(authors) {
  let out = '';
  for (const s of allSurnames(authors)) {
    const next = out ? `${out}-${s}` : s;
    if (next.length > MAX_AUTHOR_CHARS) {
      return out ? `${out}-etal` : s.slice(0, MAX_AUTHOR_CHARS);
    }
    out = next;
  }
  return out || 'unknown';
}

// ---------------------------------------------------------------------------
//  Plan
// ---------------------------------------------------------------------------
const paperSeq = new Map(); // drive_file_id -> "001"
const claimed = new Map();  // current folder -> group that claimed it
let nextSeq = 1;

return $input.all().map((item) => {
  const row = item.json;
  const skip = (reason) => ({ json: { ...row, _skip: true, _skip_reason: reason } });

  if (!row.drive_file_id || !row.variant) {
    return skip('row has no drive_file_id or variant');
  }

  if (!paperSeq.has(row.drive_file_id)) {
    paperSeq.set(row.drive_file_id, String(nextSeq++).padStart(3, '0'));
  }

  const groupKey = `${row.drive_file_id}_${row.variant}`;
  const titleSlug = slug(row.title);
  const newFolder =
    `${paperSeq.get(row.drive_file_id)}_${authorPart(row.authors)}_` +
    `${titleSlug || 'untitled'}_${row.variant}`;

  const fromNotes = (String(row.notes || '').match(/Folder renamed: (\S+) ->/) || [])[1];
  const originalPrefix = `${originalSurname(row.authors)}_${titleSlug}_${row.variant}_`;

  let current = null;
  let foundVia = '';
  if (onDisk.has(newFolder)) {
    current = newFolder; foundVia = 'new name';
  } else if (row.folder_name && onDisk.has(row.folder_name)) {
    current = row.folder_name; foundVia = 'sheet folder_name';
  } else if (fromNotes && onDisk.has(fromNotes)) {
    current = fromNotes; foundVia = 'notes';
  } else {
    const hits = [...onDisk].filter((n) => n.startsWith(originalPrefix));
    if (hits.length === 1) {
      current = hits[0]; foundVia = 'original pattern';
    } else if (hits.length > 1) {
      return skip(`ambiguous, several folders match: ${hits.join(', ')}`);
    }
  }

  if (!current) return skip(`no folder on disk (looked for ${originalPrefix}*)`);

  const owner = claimed.get(current);
  if (owner && owner !== groupKey) {
    return skip(`folder ${current} is already claimed by ${owner}`);
  }
  claimed.set(current, groupKey);

  return {
    json: {
      ...row,
      old_folder_name: current,
      new_folder_name: newFolder,
      found_via: foundVia,
      old_path: `${root}/${current}`,
      new_path: `${root}/${newFolder}`,
    },
  };
});

// ============================================================================
//  "Rename folders on disk"  —  REPLACEMENT. Paste the whole file.
//  Mode: Run Once for All Items (default).
//
//  Renames each folder once (several rows can share a folder), respects
//  Globals.DRY_RUN, and never overwrites an existing folder.
//
//  rename_status values:
//    renamed / already_renamed   -> passes the Filter, sheet gets updated
//    would_rename                -> dry run only, sheet untouched
//    target_exists / error / skipped -> sheet untouched, check the row
// ============================================================================

const fs = require('fs');
const g = $('Globals').first().json;
const dryRun = g.DRY_RUN === true || String(g.DRY_RUN).toLowerCase() === 'true';

const results = new Map(); // new folder name -> { status, error }

return $input.all().map((item) => {
  const row = item.json;
  if (row._skip) {
    return { json: { ...row, rename_status: 'skipped', rename_error: row._skip_reason } };
  }

  let r = results.get(row.new_folder_name);
  if (!r) {
    r = { status: '', error: '' };
    try {
      if (row.old_folder_name === row.new_folder_name) {
        r.status = 'already_renamed';
      } else if (fs.existsSync(row.new_path)) {
        r.status = 'target_exists';
      } else if (dryRun) {
        r.status = 'would_rename';
      } else {
        fs.renameSync(row.old_path, row.new_path);
        r.status = 'renamed';
      }
    } catch (e) {
      r.status = 'error';
      r.error = e.message;
    }
    results.set(row.new_folder_name, r);
  }

  let newNotes = row.notes || '';
  const changed = row.old_folder_name !== row.new_folder_name;
  if (changed && !newNotes.includes(`-> ${row.new_folder_name} (`)) {
    const line =
      `Folder renamed: ${row.old_folder_name} -> ${row.new_folder_name} ` +
      `(${new Date().toISOString()})`;
    newNotes = newNotes ? `${newNotes}\n${line}` : line;
  }

  return {
    json: {
      ...row,
      rename_status: r.status,
      rename_error: r.error,
      new_notes: newNotes,
    },
  };
});

// Quick overview for checking a dry run: counts per status plus every row
// that needs attention. Does not touch the disk or the sheet.
const g = $('Globals').first().json;
const all = $input.all().map((i) => i.json);

const counts = {};
const problems = [];
for (const r of all) {
  counts[r.rename_status] = (counts[r.rename_status] || 0) + 1;
  if (!['renamed', 'already_renamed', 'would_rename'].includes(r.rename_status)) {
    problems.push({
      row_key: r.row_key,
      status: r.rename_status,
      reason: r.rename_error || '',
      sheet_folder_name: r.folder_name || '',
    });
  }
}

const folders = new Set(all.map((r) => r.new_folder_name).filter(Boolean)).size;

return [{
  json: {
    dry_run: g.DRY_RUN,
    rows: all.length,
    distinct_new_folders: folders,
    counts,
    problems_count: problems.length,
    problems,
  },
}];
